#include "th10/game/shot_practice_menu.hpp"
namespace{int Clamp(int v,int n){if(n==0)return v;if(v<0)return 0;if(v>=n)return n-1;return v;}void Change(ShotPracticeState*s,ShotPracticeEnv*e,const ShotPracticeOps*o){s->previous_selection=s->selection;if((e->held&0x10u)||(e->pressed&0x10u))o->move_selection(o->context,s,-1);if((e->held&0x20u)||(e->pressed&0x20u))o->move_selection(o->context,s,1);if(s->previous_selection!=s->selection){o->play_sound(o->context,12);o->close_view(o->context,150+e->character);o->open_view(o->context,150+e->character);}}}
// 0x00430A60 - three-way shot/style menu with difficulty-4 availability filtering.
int ShotPracticeMenu_Update(ShotPracticeState*s,ShotPracticeEnv*e,const ShotPracticeOps*o){switch(s->phase){case 0:s->selection_count=3;s->unavailable_count=0;if(e->difficulty==4){for(int i=0;i<3;++i)if(!e->available[i]){s->unavailable[s->unavailable_count++]=i;if(s->selection==i){for(int j=0;j<3;++j)if(e->available[j]){s->selection=j;break;}}}}s->selection=Clamp(s->selection,s->selection_count);o->open_view(o->context,100);o->close_view(o->context,150+e->character);o->open_view(o->context,150+e->character);o->set_phase(o->context,1);break;case 1:if(s->phase_timer>6)o->set_phase(o->context,2);break;case 2:Change(s,e,o);if(e->pressed&0xAu){o->set_phase(o->context,4);o->play_sound(o->context,11);return 1;}if(e->pressed&0x1001u){o->set_phase(o->context,3);o->play_sound(o->context,10);e->shot=s->selection;return 1;}break;case 3:if(s->phase_timer==10){if(e->replay_mode){e->shot=s->selection;o->reset_selection(o->context);o->close_view(o->context,100);o->set_phase(o->context,9);}else{o->start_fade(o->context,480,384);o->play_sound(o->context,43);}}if(s->phase_timer>=40){e->shot=s->selection;o->reset_selection(o->context);if(e->replay_mode){o->close_view(o->context,100);o->set_phase(o->context,9);}else{o->set_phase(o->context,3);e->stage=e->difficulty<4?1:7;e->launch_state=7;o->launch(o->context,6);}}break;case 4:if(s->phase_timer>=6){o->close_view(o->context,150+e->character);o->close_view(o->context,100);o->set_phase(o->context,7);o->reset_selection(o->context);}break;}return 1;}
